   614  int msInitProjection(projectionObj *p)
   615  {
   616    p->gt.need_geotransform = MS_FALSE;
   617    p->numargs = 0;
   618    p->args = NULL;
   619    p->wellknownprojection = wkp_none;
   620    p->proj = NULL;
   621    p->args = (char **)malloc(MS_MAXPROJARGS*sizeof(char *));
