   631  void msFreeProjection(projectionObj *p)
   632  {
   633  #if PROJ_VERSION_MAJOR >= 6
   634    proj_destroy(p->proj);
   635    p->proj = NULL;
   636    msProjectionContextUnref(p->proj_ctx);
   637    p->proj_ctx = NULL;
   638  #else
   639    if(p->proj) {
   640      pj_free(p->proj);
   641      p->proj = NULL;
   642    }
   643  #if PJ_VERSION >= 480
   644    if(p->proj_ctx) {
   645      pj_ctx_free(p->proj_ctx);
   646      p->proj_ctx = NULL;
   647    }
   648  #endif
   649  #endif
